        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String loanId = loanBook(registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returning_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void returned_book_can_be_loaned_again() throws Exception {
        String bookId = registerBook();
        String memberId = registerMember();
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void returned_loans_do_not_count_toward_the_loan_limit() throws Exception {
        String memberId = registerMember();
        String firstLoanId = loanBook(registerBook(), memberId);
        for (int i = 0; i < 4; i++) {
            loanBook(registerBook(), memberId);
        }

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void loan_with_loaned_at_uses_the_given_date_and_sets_due_date_14_days_later() throws Exception {
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), registerMember(), LocalDate.of(2026, 1, 1))))
                .andExpect(status().isCreated())
