package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.ListReservationsUseCase;
import com.example.lending.application.port.in.PlaceReservationUseCase;
import com.example.lending.application.port.in.PlaceReservationUseCase.PlaceReservationCommand;
import com.example.lending.application.port.in.QueuedReservation;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books/{bookId}/reservations")
public class ReservationController {

    private final PlaceReservationUseCase placeReservationUseCase;
    private final ListReservationsUseCase listReservationsUseCase;

    public ReservationController(PlaceReservationUseCase placeReservationUseCase,
                                 ListReservationsUseCase listReservationsUseCase) {
        this.placeReservationUseCase = placeReservationUseCase;
        this.listReservationsUseCase = listReservationsUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ReservationResponse placeReservation(@PathVariable UUID bookId,
                                                @RequestBody PlaceReservationRequest request) {
        QueuedReservation queued = placeReservationUseCase.placeReservation(
                new PlaceReservationCommand(bookId, request.memberId()));
        return ReservationResponse.from(queued);
    }

    @GetMapping
    public List<WaitingReservationResponse> listReservations(@PathVariable UUID bookId) {
        return listReservationsUseCase.listReservations(bookId).stream()
                .map(WaitingReservationResponse::from)
                .toList();
    }
}
