package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409_book_available() throws Exception {
        String bookId = registerBook();

        mockMvc.perform(reserve(bookId, registerMember()))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_loaned_book_returns_201_with_position_starting_at_1() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());

        mockMvc.perform(reserve(bookId, registerMember()))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").isNotEmpty())
                .andExpect(jsonPath("$.position").value(1));
    }

    @Test
    void later_reservers_get_the_next_positions_in_line() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());

        reserveAndExpectPosition(bookId, registerMember(), 1);
        reserveAndExpectPosition(bookId, registerMember(), 2);
        reserveAndExpectPosition(bookId, registerMember(), 3);
    }

    @Test
    void same_member_cannot_reserve_the_same_book_twice() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());
        String memberId = registerMember();
        reserveAndExpectPosition(bookId, memberId, 1);

        mockMvc.perform(reserve(bookId, memberId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void reserving_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(reserve(UUID.randomUUID().toString(), registerMember()))
                .andExpect(status().isNotFound());
    }

    @Test
    void reserving_with_an_unregistered_member_returns_404() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());

        mockMvc.perform(reserve(bookId, UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    @Test
    void reserving_a_discarded_book_returns_409_book_discarded() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());
        mockMvc.perform(post("/books/{bookId}/discard", bookId)).andExpect(status().isConflict());

        mockMvc.perform(reserve(bookId, registerMember()))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void list_returns_waiting_reservations_in_line_order() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());
        String firstMemberId = registerMember();
        String secondMemberId = registerMember();
        String firstReservationId = reserveAndExpectPosition(bookId, firstMemberId, 1);
        String secondReservationId = reserveAndExpectPosition(bookId, secondMemberId, 2);

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].reservationId").value(firstReservationId))
                .andExpect(jsonPath("$[0].memberId").value(firstMemberId))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].reservationId").value(secondReservationId))
                .andExpect(jsonPath("$[1].memberId").value(secondMemberId))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void list_of_unknown_book_returns_404() throws Exception {
        mockMvc.perform(get("/books/{bookId}/reservations", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void after_return_a_non_first_reserver_cannot_loan_the_book() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());
        reserveAndExpectPosition(bookId, registerMember(), 1);
        reserveAndExpectPosition(bookId, registerMember(), 2);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(loan(bookId, registerMember()))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
    }

    @Test
    void after_return_the_first_reserver_can_loan_and_the_next_one_moves_to_the_front() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());
        String firstMemberId = registerMember();
        String secondMemberId = registerMember();
        reserveAndExpectPosition(bookId, firstMemberId, 1);
        reserveAndExpectPosition(bookId, secondMemberId, 2);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(loan(bookId, firstMemberId)).andExpect(status().isCreated());

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(secondMemberId))
                .andExpect(jsonPath("$[0].position").value(1));
        mockMvc.perform(loan(bookId, secondMemberId))
                .andExpect(status().isConflict());
    }

    @Test
    void after_the_first_reserver_loans_the_next_one_can_loan_too() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());
        String firstMemberId = registerMember();
        String secondMemberId = registerMember();
        reserveAndExpectPosition(bookId, firstMemberId, 1);
        reserveAndExpectPosition(bookId, secondMemberId, 2);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());
        mockMvc.perform(loan(bookId, firstMemberId)).andExpect(status().isCreated());
        String secondLoanId = loanIdOf(loan(bookId, firstMemberId).andReturn());
        mockMvc.perform(post("/loans/{loanId}/return", secondLoanId)).andExpect(status().isOk());

        mockMvc.perform(loan(bookId, secondMemberId)).andExpect(status().isCreated());
    }

    @Test
    void reserved_book_without_reservers_is_still_loanable_by_anyone() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(loan(bookId, registerMember())).andExpect(status().isCreated());
    }

    private String reserveAndExpectPosition(String bookId, String memberId, int position) throws Exception {
        String body = mockMvc.perform(reserve(bookId, memberId))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(position))
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("reservationId").asText();
    }

    private org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder reserve(String bookId,
                                                                                              String memberId) {
        return post("/books/{bookId}/reservations", bookId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"memberId\":\"" + memberId + "\"}");
    }

    private org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder loan(String bookId,
                                                                                           String memberId) {
        return post("/loans")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}");
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(loan(bookId, memberId))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return loanIdOf(loaned);
    }

    private String loanIdOf(org.springframework.test.web.servlet.MvcResult result) throws Exception {
        return loanIdOf(result.getResponse().getContentAsString());
    }

    private String loanIdOf(String json) throws Exception {
        JsonNode loan = objectMapper.readTree(json);
        return loan.get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }
}

