package com.example.lending.domain;

import java.util.Objects;
import java.util.UUID;

public class Reservation {

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private boolean fulfilled;

    private Reservation(UUID id, UUID bookId, UUID memberId, boolean fulfilled) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.fulfilled = fulfilled;
    }

    public static Reservation place(UUID bookId, UUID memberId) {
        return new Reservation(UUID.randomUUID(), bookId, memberId, false);
    }

    public static Reservation reconstitute(UUID id, UUID bookId, UUID memberId, boolean fulfilled) {
        return new Reservation(id, bookId, memberId, fulfilled);
    }

    void fulfill() {
        if (fulfilled) {
            throw new IllegalStateException("reservation is already fulfilled: " + id);
        }
        this.fulfilled = true;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public boolean isFulfilled() {
        return fulfilled;
    }
}
package com.example.lending.domain;

import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

/**
 * 한 책의 대기 예약 줄. 생성자에 넘기는 목록은 줄 순서(맨 앞이 첫 번째)여야 한다.
 */
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> waiting;

    public ReservationQueue(UUID bookId, List<Reservation> waiting) {
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.waiting = List.copyOf(waiting);
    }

    public void ensureNotReservedBy(UUID memberId) {
        boolean alreadyReserved = waiting.stream().anyMatch(r -> r.getMemberId().equals(memberId));
        if (alreadyReserved) {
            throw new AlreadyReservedException(bookId, memberId);
        }
    }

    public int nextPosition() {
        return waiting.size() + 1;
    }

    public List<Reservation> asList() {
        return waiting;
    }

    /**
     * 대출하려는 회원이 줄 맨 앞이면 그 예약을 소진하고 반환한다. 예약이 없으면 빈 값을 반환한다.
     * 맨 앞이 아니면 다른 회원의 예약이므로 대출을 거절한다.
     */
    public Optional<Reservation> fulfillFor(UUID memberId) {
        if (waiting.isEmpty()) {
            return Optional.empty();
        }
        Reservation head = waiting.get(0);
        if (!head.getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(bookId);
        }
        head.fulfill();
        return Optional.of(head);
    }
}
