public class BookAvailableException extends RuntimeException {

    public BookAvailableException(UUID bookId) {
        super("book is available, no need to reserve: " + bookId);
    }
}
package com.example.lending.domain;

import java.util.UUID;

public class ReservedForOtherException extends RuntimeException {

    public ReservedForOtherException(UUID bookId) {
        super("book is reserved for another member: " + bookId);
    }
}
